def route_for(path):
    rel = path.relative_to(ROOT).as_posix()
    if rel == "index.html": return "/"
    if rel.endswith("/index.html"): return "/" + rel[:-10]
    if rel.endswith(".html"): return "/" + rel[:-5] + "/"
    return None

for rel, content in PAGES.items():
    path = ROOT / rel; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(content, encoding="utf-8")

# Canonical duplicate files stay out of search and redirect through _redirects.
for alias, canonical in (("pricing.html", "pricing/index.html"), ("free-business-review.html", "free-business-review/index.html"), ("about.html", "about/index.html"), ("resources.html", "resources/index.html")):
    (ROOT / alias).write_text((ROOT / canonical).read_text(encoding="utf-8").replace('content="index,follow,max-image-preview:large"', 'content="noindex,follow"'), encoding="utf-8")

